    {
      "keystrokes": "printf 'hello world\\nfoo bar\\nhello foo\\n' > /tmp/t.txt; python -c 'import fasttext; m=fasttext.train_unsupervised(\"/tmp/t.txt\"); print(m.get_words()[:5])'\n",
      "duration": 5.0
    }
  ]
